'stem-chateau-badette|2012':{blend:{ME:90,CF:7,PV:3},src:'Chateau-Badette-2012-FR.pdf'},
'stem-chateau-badette|2013':{blend:{ME:85,CF:10,PV:5},src:'Chateau-Badette-2013-FR.pdf'},
